-- Annual assessment workflow: journal versions, finding resolutions, attestations, final approval.
alter table public.case_reviews add column if not exists workflow jsonb;

-- Journal corrections re-run the analysis; the normalized copies are regenerated by any member of the
-- organization (the authoritative analysis is case_reviews.analysis; changes are audited).
create policy extracted_facts_delete_member on public.extracted_facts for delete to authenticated using (organization_id = public.current_org_id());
create policy qa_results_delete_member on public.qa_results for delete to authenticated using (organization_id = public.current_org_id());
create policy discrepancies_delete_member on public.discrepancies for delete to authenticated using (organization_id = public.current_org_id());
